@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap');

:root {
  color-scheme: light;
  --paper: #f3f2ed;
  --surface: #fffefa;
  --surface-muted: #f8f7f2;
  --ink: #202a26;
  --muted: #78827c;
  --faint: #a4aca5;
  --line: #e4e6df;
  --line-strong: #d7dad1;
  --gold: #a87936;
  --gold-pale: #f5efdf;
  --green: #477d65;
  --red: #b65f52;
  --blue: #6389a0;
  --mono: 'DM Mono', monospace;
  --sans: 'DM Sans', sans-serif;
  --serif: 'Playfair Display', Georgia, serif;
}
* { box-sizing: border-box; }
html { min-width: 320px; background: var(--paper); }
body { margin: 0; min-height: 100vh; color: var(--ink); background: var(--paper); font-family: var(--sans); -webkit-font-smoothing: antialiased; }
button, input, select { font: inherit; }
button { color: inherit; cursor: pointer; }
button:focus-visible, input:focus-visible, select:focus-visible { outline: 2px solid #8eaa96; outline-offset: 2px; }
button:disabled { cursor: not-allowed; }
#app { max-width: 1540px; margin: 0 auto; padding: 0 42px 38px; }
.topbar { height: 72px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--line-strong); margin-bottom: 31px; }
.brand { display: flex; align-items: center; gap: 12px; font-size: 12px; font-weight: 700; letter-spacing: .18em; }
.sigil { width: 27px; height: 27px; display: grid; place-items: center; border: 1px solid var(--gold); color: var(--gold); transform: rotate(45deg); font-size: 13px; }
.sigil span { transform: rotate(-45deg); }
.brand small { display: block; margin-top: 3px; color: var(--muted); font: 8px var(--mono); letter-spacing: .17em; }
.top-right { display: flex; align-items: center; gap: 20px; color: var(--muted); font: 9px var(--mono); letter-spacing: .1em; }
.live { color: var(--green); }
.live::before { content: ''; display: inline-block; width: 6px; height: 6px; margin: 0 8px 1px 0; border-radius: 50%; background: var(--green); }
.icon-btn { width: 32px; height: 32px; border: 1px solid var(--line-strong); border-radius: 50%; background: transparent; color: var(--gold); transition: .2s; }
.icon-btn:hover { background: var(--gold-pale); }
.layout { display: grid; grid-template-columns: minmax(0, 1fr) 316px; gap: 30px; align-items: start; }
.maincol { min-width: 0; }
.level-head { display: flex; align-items: flex-end; justify-content: space-between; padding: 1px 2px 15px; }
.eyebrow { color: var(--muted); font: 9px var(--mono); letter-spacing: .13em; }
.eyebrow span { color: var(--faint); margin: 0 5px; }
.eyebrow b { color: var(--gold); font-weight: 400; }
h1 { margin: 7px 0 0; font: 600 38px/1.1 var(--serif); letter-spacing: .01em; }
h1 i { margin-left: 8px; color: var(--faint); font: 12px var(--mono); font-style: normal; }
.floor-state { padding-bottom: 7px; color: var(--muted); font: 9px var(--mono); letter-spacing: .1em; }
.status-dot { width: 6px; height: 6px; display: inline-block; margin: 0 8px 1px 0; border-radius: 50%; background: var(--green); }
.scene-wrap { position: relative; height: clamp(310px, 38vw, 460px); min-height: 300px; overflow: hidden; border: 1px solid #d6d9d0; background: #d9e1d8; box-shadow: 0 12px 30px #4e574513; }
.scene-wrap::after { position: absolute; inset: 0; content: ''; pointer-events: none; background: linear-gradient(90deg, #18221b14, transparent 22%, transparent 78%, #18221b12), linear-gradient(0deg, #111b1726, transparent 34%, #fff1 100%); }
.scene-wrap canvas { display: block; width: 100%; height: 100%; }
.scene-top { position: absolute; top: 16px; left: 17px; right: 17px; display: flex; justify-content: space-between; align-items: center; color: #53625a; font: 8px var(--mono); letter-spacing: .13em; pointer-events: none; }
.scene-tag { padding: 8px 10px; border: 1px solid #fff9; background: #fffefaad; color: #46534b; backdrop-filter: blur(8px); }
.scene-tag i { margin-right: 5px; color: var(--gold); font-style: normal; }
.scene-bottom { position: absolute; right: 20px; bottom: 18px; left: 20px; display: flex; align-items: end; justify-content: space-between; pointer-events: none; }
.scene-bottom strong { display: block; color: #fffefa; text-shadow: 0 1px 9px #202a26a6; font: 600 16px var(--serif); letter-spacing: .08em; }
.scene-bottom small { display: block; margin-top: 5px; color: #f0f2eb; text-shadow: 0 1px 8px #202a26b3; font: 8px var(--mono); letter-spacing: .1em; }
.enemy-health { width: 33%; max-width: 245px; }
.barline, .vital-label, .level-line { display: flex; align-items: center; justify-content: space-between; margin-bottom: 6px; color: #f3f2ed; font: 8px var(--mono); letter-spacing: .08em; }
.barline span:last-child { color: #fffefa; }
.bar { position: relative; height: 5px; overflow: hidden; background: #28332d20; }
.bar i { display: block; width: 100%; height: 100%; background: var(--red); transition: width .25s ease; }
.enemy-health .bar { background: #fff9; }
.enemy-health .bar i { background: #c85e51; }
.toast { position: absolute; z-index: 2; top: 48%; left: 50%; transform: translate(-50%, -50%); color: #fffefa; text-shadow: 0 2px 15px #202a26; opacity: 0; pointer-events: none; font: 500 12px var(--mono); letter-spacing: .16em; white-space: nowrap; transition: opacity .2s; }
.toast.show { opacity: 1; }
.combat-row { height: 76px; display: flex; align-items: center; justify-content: space-between; }
.hero-vitals { display: flex; align-items: center; gap: 12px; width: 43%; max-width: 330px; }
.portrait { position: relative; width: 40px; height: 40px; display: grid; flex: 0 0 auto; place-items: center; border: 1px solid #d8c99e; background: var(--gold-pale); color: var(--gold); font-size: 18px; }
.portrait span { position: absolute; right: -5px; bottom: -5px; padding: 2px 3px; background: var(--surface); color: var(--muted); font: 7px var(--mono); }
.vital-stack { flex: 1; min-width: 0; }
.vital-label { margin: 0 0 4px; color: var(--muted); font-size: 7px; }
.vital-label b { color: var(--ink); font-weight: 400; }
.vital-stack .bar { height: 4px; margin-bottom: 7px; background: #e4e6df; }
.bar.hp i { background: #6d9c79; }
.bar.mp i { background: #7095ad; }
.combat-note { color: var(--muted); font: 8px var(--mono); letter-spacing: .04em; }
.keycap { display: inline-block; padding: 3px 4px; border: 1px solid var(--line-strong); color: var(--ink); font: 7px var(--mono); }
.sep { margin: 0 8px; color: var(--faint); }
.actions { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 9px; }
.action { position: relative; display: flex; height: 62px; align-items: center; gap: 10px; overflow: hidden; padding: 0 12px; border: 1px solid var(--line-strong); background: var(--surface); text-align: left; transition: .18s; }
.action:hover:not(:disabled) { transform: translateY(-2px); border-color: #b99a61; box-shadow: 0 5px 15px #6c60400e; }
.action:active:not(:disabled) { transform: translateY(0); }
.action:disabled { opacity: .48; }
.action.primary { border-color: #c5aa76; background: #fbf8ef; }
.action-icon { width: 23px; flex: 0 0 auto; color: var(--gold); font-size: 19px; text-align: center; }
.skill .action-icon { color: #6389a0; }
.evade .action-icon { color: var(--green); }
.potion .action-icon { color: var(--red); }
.action b { display: block; font: 500 8px var(--mono); letter-spacing: .07em; white-space: nowrap; }
.action small { display: block; margin-top: 5px; color: var(--muted); font: 7px var(--mono); white-space: nowrap; }
.action kbd { margin-left: 2px; padding: 1px 3px; border: 1px solid var(--line); font: 7px var(--mono); }
.cooldown { position: absolute; bottom: 0; left: 0; width: 0; height: 2px; background: var(--gold); transition: width .12s; }
.log-wrap { margin-top: 20px; padding-top: 12px; border-top: 1px solid var(--line-strong); }
.section-title, .panel-title { display: flex; align-items: center; justify-content: space-between; color: var(--muted); font: 8px var(--mono); letter-spacing: .13em; }
.section-title span { color: var(--faint); font-size: 7px; }
.combat-log { height: 62px; display: flex; flex-direction: column-reverse; gap: 4px; overflow: hidden; padding-top: 7px; }
.log-entry { color: var(--muted); font: 9px var(--mono); animation: appear .24s; }
.log-entry b { color: var(--ink); font-weight: 500; }
.log-entry .damage { color: var(--red); }
.log-entry .good { color: var(--green); }
.log-entry .gold { color: var(--gold); }
@keyframes appear { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }

