@keyframes appear { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
.sidebar { display: flex; flex-direction: column; gap: 11px; }
.panel { min-width: 0; padding: 15px 16px; border: 1px solid var(--line); background: var(--surface); }
.panel-title { padding-bottom: 11px; border-bottom: 1px solid var(--line); }
.more { color: var(--faint); letter-spacing: .2em; }
.profile-main { display: flex; align-items: center; gap: 12px; padding: 13px 0 11px; }
.avatar { width: 42px; height: 42px; display: grid; flex: 0 0 auto; place-items: center; border: 1px solid #d8c99e; background: var(--gold-pale); color: var(--gold); font-size: 19px; }
.profile-main h2 { margin: 0 0 5px; font: 600 15px var(--serif); }
.rank { color: var(--muted); font: 7px var(--mono); letter-spacing: .06em; }
.rank span { margin-right: 4px; color: var(--gold); }
.level-line { margin: 2px 0 6px; color: var(--muted); font-size: 7px; }
.level-line b { margin-left: 4px; color: var(--ink); font-weight: 500; }
.bar.xp { height: 3px; background: #e7e5dc; }
.bar.xp i { background: #c4a366; transition: width .3s; }
.stats { display: grid; grid-template-columns: repeat(4, 1fr); margin: 13px -2px 0; padding-top: 10px; border-top: 1px solid var(--line); }
.stats div { position: relative; display: flex; flex-direction: column; gap: 4px; padding-left: 9px; border-right: 1px solid var(--line); }
.stats div:first-child { padding-left: 0; }
.stats div:last-child { border: 0; }
.stats small { color: var(--muted); font: 6px var(--mono); letter-spacing: .03em; }
.stats b { color: var(--ink); font: 12px var(--mono); font-weight: 400; }
.stat-add { width: 19px; height: 19px; margin-top: 2px; padding: 0; border: 1px solid #d8c99e; background: var(--gold-pale); color: var(--gold); font: 12px var(--mono); line-height: 16px; }
.stat-add:hover { background: #eee2c3; }
.allocate { width: 100%; margin-top: 11px; padding: 8px; border: 1px solid #d8c99e; background: var(--gold-pale); color: var(--gold); font: 8px var(--mono); letter-spacing: .08em; }
.allocate:hover { background: #eee6d4; }
.hidden { display: none !important; }
.quest-mark { color: var(--gold); font-size: 13px; }
.quest { display: flex; gap: 10px; padding: 13px 0 10px; }
.quest-icon { width: 31px; height: 31px; display: grid; flex: 0 0 auto; place-items: center; border: 1px solid #e8dfcb; background: #faf7ee; color: var(--gold); }
.quest b { color: var(--ink); font: 600 10px var(--sans); }
.quest p, .services p, .floor-travel p, .npc-panel > p { margin: 6px 0 0; color: var(--muted); font-size: 9px; line-height: 1.55; }
.quest-progress { display: flex; align-items: center; gap: 10px; color: var(--muted); font: 7px var(--mono); }
.quest-progress .bar { flex: 1; height: 3px; }
.quest-progress .bar i { background: #b69a62; }
.reward { display: flex; justify-content: space-between; margin-top: 12px; padding-top: 9px; border-top: 1px solid var(--line); font: 7px var(--mono); }
.reward > span { color: var(--muted); letter-spacing: .08em; }
.reward b { color: var(--gold); font-weight: 400; }
.reward i { color: var(--faint); font-style: normal; }
.tower-visual { position: relative; height: 95px; margin-top: 12px; overflow: hidden; background: linear-gradient(150deg, #f1f0e9, #e5e8df); }
.tower-visual::before { position: absolute; right: 12px; bottom: -34px; width: 75px; height: 130px; content: ''; border: 1px solid #c6cabe; border-bottom: 0; background: repeating-linear-gradient(0deg, transparent 0 16px, #c6cabe 17px 18px); clip-path: polygon(39% 0, 60% 0, 100% 100%, 0 100%); }
.tower-silhouette { position: absolute; inset: 0; display: flex; align-items: end; justify-content: flex-end; gap: 7px; padding: 0 36px 0 0; opacity: .7; }
.tower-silhouette i { width: 9px; height: 25px; border: 1px solid #c5cabb; border-bottom: 0; background: repeating-linear-gradient(0deg, transparent 0 8px, #c5cabb 9px 10px); }
.tower-silhouette i:nth-child(2) { height: 38px; }
.tower-silhouette i:nth-child(3) { height: 48px; }
.tower-silhouette i:nth-child(4) { height: 33px; }
.tower-silhouette i:nth-child(5) { height: 58px; }
.tower-copy { position: absolute; top: 15px; left: 15px; display: flex; flex-direction: column; }
.tower-copy b { color: #5b654d; font: 600 25px var(--serif); }
.tower-copy small { color: var(--muted); font: 7px var(--mono); letter-spacing: .07em; }
.tower-copy span { margin-top: 7px; color: var(--gold); font: 7px var(--mono); letter-spacing: .08em; }
.floor-list { display: flex; gap: 4px; margin-top: 8px; }
.floor-list span, .floor-list button { width: 21px; height: 20px; display: grid; place-items: center; border: 1px solid var(--line); background: var(--surface-muted); color: var(--muted); font: 7px var(--mono); }
.floor-list .active { border-color: #cbb783; background: var(--gold-pale); color: var(--gold); }
.gear-row { display: flex; align-items: center; gap: 9px; padding: 11px 0; border-bottom: 1px solid var(--line); }
.gear-icon { width: 30px; height: 30px; display: grid; flex: 0 0 auto; place-items: center; border: 1px solid var(--line); background: var(--surface-muted); color: var(--gold); font-size: 14px; }
.gear-icon.armor { color: var(--blue); }
.gear-row > div:nth-child(2) { min-width: 0; }
