.relic-row small { margin-left: auto; color: var(--muted); font: 7px var(--mono); white-space: nowrap; }
.rarity-dot { width: 6px; height: 6px; flex: 0 0 auto; border-radius: 50%; background: var(--gold); }
.loot-summary { margin-top: 8px; color: var(--muted); font: 7px var(--mono); }
.tonic-use, .service-actions button, .travel-row button, .resident-tools button, .quest-card button { border: 1px solid var(--line-strong); background: var(--surface-muted); color: var(--ink); font: 7px var(--mono); letter-spacing: .03em; }
.tonic-use { width: 100%; margin-top: 10px; padding: 8px; color: var(--blue); text-align: center; }
.tonic-use:hover:not(:disabled), .service-actions button:hover:not(:disabled), .travel-row button:hover, .resident-tools button:hover:not(:disabled), .quest-card button:hover:not(:disabled) { border-color: #c4aa78; background: var(--gold-pale); }
.service-actions { display: grid; gap: 5px; margin-top: 10px; }
.service-actions button { padding: 7px 8px; text-align: left; }
.service-actions button:disabled, .tonic-use:disabled, .resident-tools button:disabled, .quest-card button:disabled { opacity: .48; }
.gold-text { color: var(--gold); }
.floor-travel .travel-row { display: flex; gap: 6px; margin-top: 10px; }
.travel-row select { width: 100%; min-width: 0; padding: 7px; border: 1px solid var(--line-strong); background: var(--surface-muted); color: var(--ink); font: 8px var(--mono); }
.travel-row button { padding: 0 10px; color: var(--gold); }
.npc-locked { background: #fcfbf7; }
.resident-tools { display: grid; gap: 6px; margin-top: 10px; }
.resident-tools > button { padding: 8px; color: var(--gold); }
.resident-tools form { display: flex; gap: 5px; }
.resident-tools input, .chat-form input { width: 100%; min-width: 0; padding: 7px 8px; border: 1px solid var(--line-strong); background: var(--surface-muted); color: var(--ink); font: 8px var(--sans); }
.resident-tools form button { padding: 0 9px; }
.resident-card, .quest-card { margin-top: 10px; padding: 10px; border: 1px solid var(--line); background: var(--surface-muted); }
.resident-card > div, .quest-card > div { display: flex; align-items: flex-start; justify-content: space-between; gap: 7px; }
.resident-card b, .quest-card b { color: var(--ink); font: 600 9px var(--sans); }
.resident-card small, .quest-card small { display: block; margin-top: 3px; color: var(--gold); font: 7px var(--mono); }
#npcMood { color: var(--green); font: 6px var(--mono); white-space: nowrap; }
.resident-card p, .quest-card p { margin: 8px 0 0; color: var(--muted); font-size: 8px; line-height: 1.5; }
.quest-card button { width: 100%; margin-top: 9px; padding: 7px; }
.chat-log { max-height: 140px; margin-top: 9px; overflow-y: auto; }
.chat-log p { margin: 5px 0; color: var(--muted); font-size: 8px; line-height: 1.5; }
.chat-log .chat-system { color: var(--faint); font-style: italic; }
.chat-form { display: flex; gap: 5px; margin-top: 7px; }
.chat-form button { padding: 0 9px; border: 1px solid var(--line-strong); background: var(--surface-muted); color: var(--gold); font: 7px var(--mono); }
.continue { width: 100%; display: flex; justify-content: center; align-items: center; gap: 9px; margin-top: 4px; padding: 12px; border: 1px solid #c4aa78; background: var(--gold-pale); color: var(--gold); font: 8px var(--mono); letter-spacing: .08em; }
.continue:hover { background: #eee5d2; }
.footnote { display: flex; justify-content: space-between; padding: 2px 2px 0; color: var(--faint); font: 6px var(--mono); letter-spacing: .06em; }
.modal { position: fixed; z-index: 10; inset: 0; display: grid; place-items: center; padding: 20px; background: #202a2666; backdrop-filter: blur(4px); }
.modal-card { width: min(100%, 390px); padding: 34px 30px; border: 1px solid var(--line-strong); background: var(--surface); text-align: center; box-shadow: 0 20px 70px #202a2633; }
.modal-sigil { margin-bottom: 16px; color: var(--gold); font-size: 27px; }
.modal-card h2 { margin: 9px 0; font: 600 25px var(--serif); }
.modal-card p { color: var(--muted); font-size: 12px; line-height: 1.6; }
.modal-card button { margin-top: 13px; padding: 11px 17px; border: 1px solid #c4aa78; background: var(--gold-pale); color: var(--gold); font: 8px var(--mono); letter-spacing: .07em; }
#scene.shake { animation: combat-shake .26s linear; }
@keyframes combat-shake { 0%, 100% { transform: translateX(0); } 20%, 60% { transform: translateX(-5px); } 40%, 80% { transform: translateX(5px); } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; } #scene.shake { animation: none; } }
@media (max-width: 1100px) {
  #app { padding-right: 24px; padding-left: 24px; }
  .layout { grid-template-columns: minmax(0, 1fr) 290px; gap: 17px; }
  .panel { padding: 13px; }
  .action { gap: 7px; padding: 0 8px; }
  .action b { font-size: 7px; }
  .action small { font-size: 6px; }
}
@media (max-width: 800px) {
  #app { padding: 0 16px 25px; }
  .topbar { height: 60px; margin-bottom: 18px; }
  .layout { display: flex; flex-direction: column; gap: 17px; }
  .maincol, .sidebar { width: 100%; }
  .sidebar { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
  .panel { padding: 13px; }
  .scene-wrap { height: clamp(300px, 58vw, 430px); }
  .action { height: 59px; padding: 0 12px; }
  .action b { font-size: 8px; }
  .action small { font-size: 7px; }
  .continue, .footnote { grid-column: 1 / -1; }
}
@media (max-width: 520px) {
  #app { padding: 0 12px 20px; }
  .topbar { height: 52px; margin-bottom: 14px; }
  .brand { gap: 9px; font-size: 10px; }
  .sigil { width: 23px; height: 23px; font-size: 11px; }
  .brand small { font-size: 7px; }
  .top-right { gap: 10px; font-size: 7px; }
  .top-right #clock { display: none; }
  .level-head { padding-bottom: 10px; }
  h1 { font-size: 31px; }
  .eyebrow { font-size: 7px; }
  .floor-state { padding-bottom: 5px; font-size: 7px; }
  .scene-wrap { height: 300px; min-height: 280px; }
  .scene-top { top: 12px; right: 11px; left: 11px; font-size: 7px; }
  .scene-tag { padding: 7px 8px; }
  .scene-bottom { right: 12px; bottom: 13px; left: 12px; }
  .scene-bottom strong { font-size: 12px; }
  .scene-bottom small { font-size: 7px; }
  .enemy-health { width: 43%; }
  .combat-row { height: 69px; }
  .hero-vitals { width: 53%; gap: 9px; }
  .portrait { width: 35px; height: 35px; }
  .combat-note { max-width: 145px; font-size: 0; text-align: right; line-height: 2; }
  .combat-note .keycap { font-size: 7px; }
  .combat-note .sep { margin: 0 4px; font-size: 8px; }
  .actions { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 7px; }
  .action { height: 55px; gap: 7px; padding: 0 10px; }
  .action-icon { width: 20px; font-size: 17px; }
  .sidebar { gap: 8px; }
  .panel { padding: 11px; }
  .panel-title { font-size: 7px; }
  .stats div { padding-left: 5px; }
  .stats small { font-size: 5px; }
  .stats b { font-size: 11px; }
  .floor-list { flex-wrap: wrap; }
}
@media (max-width: 370px) {
  .sidebar { grid-template-columns: 1fr; }
  .action { padding: 0 8px; }
  .action b { font-size: 7px; }
  .action small { font-size: 6px; }
  .floor-state { max-width: 110px; text-align: right; line-height: 1.6; }
}

