159: .gear-row > div:nth-child(2) { min-width: 0; }
160: .gear-row b { display: block; overflow: hidden; color: var(--ink); font: 500 9px var(--sans); text-overflow: ellipsis; white-space: nowrap; }
161: .gear-row small { display: block; margin-top: 3px; color: var(--muted); font: 7px var(--mono); }
162: .gear-slot { margin-left: auto; color: var(--faint); font: 6px var(--mono); letter-spacing: .04em; }
163: .rarity-label { letter-spacing: .08em; }
164: .common { color: var(--muted) !important; }
165: .uncommon { color: var(--green) !important; }
166: .rare { color: var(--blue) !important; }
167: .epic { color: #8c69aa !important; }
168: .legendary { color: #b88628 !important; }
169: .rarity-loot { margin-top: 4px; }
170: .relic-row { display: flex; min-width: 0; align-items: center; gap: 6px; padding: 5px 0; border-bottom: 1px solid var(--line); }
171: .relic-row b { overflow: hidden; font: 7px var(--mono); text-overflow: ellipsis; white-space: nowrap; }
172: .relic-row small { margin-left: auto; color: var(--muted); font: 7px var(--mono); white-space: nowrap; }
173: .rarity-dot { width: 6px; height: 6px; flex: 0 0 auto; border-radius: 50%; background: var(--gold); }
174: .loot-summary { margin-top: 8px; color: var(--muted); font: 7px var(--mono); }
175: .tonic-use, .service-actions button, .travel-row button, .resident-tools button, .quest-card button { border: 1px solid var(--line-strong); background: var(--surface-muted); color: var(--ink); font: 7px var(--mono); letter-spacing: .03em; }
176: .tonic-use { width: 100%; margin-top: 10px; padding: 8px; color: var(--blue); text-align: center; }
177: .tonic-use:hover:not(:disabled), .service-actions button:hover:not(:disabled), .travel-row button:hover, .resident-tools button:hover:not(:disabled), .quest-card button:hover:not(:disabled) { border-color: #c4aa78; background: var(--gold-pale); }
178: .service-actions { display: grid; gap: 5px; margin-top: 10px; }
179: .service-actions button { padding: 7px 8px; text-align: left; }
180: .service-actions button:disabled, .tonic-use:disabled, .resident-tools button:disabled, .quest-card button:disabled { opacity: .48; }
181: .gold-text { color: var(--gold); }
182: .floor-travel .travel-row { display: flex; gap: 6px; margin-top: 10px; }
183: .travel-row select { width: 100%; min-width: 0; padding: 7px; border: 1px solid var(--line-strong); background: var(--surface-muted); color: var(--ink); font: 8px var(--mono); }
184: .travel-row button { padding: 0 10px; color: var(--gold); }
185: .npc-locked { background: #fcfbf7; }
186: .resident-tools { display: grid; gap: 6px; margin-top: 10px; }
187: .resident-tools > button { padding: 8px; color: var(--gold); }
188: .resident-tools form { display: flex; gap: 5px; }
189: .resident-tools input, .chat-form input { width: 100%; min-width: 0; padding: 7px 8px; border: 1px solid var(--line-strong); background: var(--surface-muted); color: var(--ink); font: 8px var(--sans); }
190: .resident-tools form button { padding: 0 9px; }
191: .resident-card, .quest-card { margin-top: 10px; padding: 10px; border: 1px solid var(--line); background: var(--surface-muted); }
192: .resident-card > div, .quest-card > div { display: flex; align-items: flex-start; justify-content: space-between; gap: 7px; }
193: .resident-card b, .quest-card b { color: var(--ink); font: 600 9px var(--sans); }
194: .resident-card small, .quest-card small { display: block; margin-top: 3px; color: var(--gold); font: 7px var(--mono); }
195: #npcMood { color: var(--green); font: 6px var(--mono); white-space: nowrap; }
196: .resident-card p, .quest-card p { margin: 8px 0 0; color: var(--muted); font-size: 8px; line-height: 1.5; }
197: .quest-card button { width: 100%; margin-top: 9px; padding: 7px; }
198: .chat-log { max-height: 140px; margin-top: 9px; overflow-y: auto; }
199: .chat-log p { margin: 5px 0; color: var(--muted); font-size: 8px; line-height: 1.5; }
200: .chat-log .chat-system { color: var(--faint); font-style: italic; }
201: .chat-form { display: flex; gap: 5px; margin-top: 7px; }
202: .chat-form button { padding: 0 9px; border: 1px solid var(--line-strong); background: var(--surface-muted); color: var(--gold); font: 7px var(--mono); }
203: .continue { width: 100%; display: flex; justify-content: center; align-items: center; gap: 9px; margin-top: 4px; padding: 12px; border: 1px solid #c4aa78; background: var(--gold-pale); color: var(--gold); font: 8px var(--mono); letter-spacing: .08em; }
204: .continue:hover { background: #eee5d2; }
205: .footnote { display: flex; justify-content: space-between; padding: 2px 2px 0; color: var(--faint); font: 6px var(--mono); letter-spacing: .06em; }
206: .modal { position: fixed; z-index: 10; inset: 0; display: grid; place-items: center; padding: 20px; background: #202a2666; backdrop-filter: blur(4px); }
207: .modal-card { width: min(100%, 390px); padding: 34px 30px; border: 1px solid var(--line-strong); background: var(--surface); text-align: center; box-shadow: 0 20px 70px #202a2633; }
208: .modal-sigil { margin-bottom: 16px; color: var(--gold); font-size: 27px; }
209: .modal-card h2 { margin: 9px 0; font: 600 25px var(--serif); }
210: .modal-card p { color: var(--muted); font-size: 12px; line-height: 1.6; }
211: .modal-card button { margin-top: 13px; padding: 11px 17px; border: 1px solid #c4aa78; background: var(--gold-pale); color: var(--gold); font: 8px var(--mono); letter-spacing: .07em; }
212: #scene.shake { animation: combat-shake .26s linear; }
213: @keyframes combat-shake { 0%, 100% { transform: translateX(0); } 20%, 60% { transform: translateX(-5px); } 40%, 80% { transform: translateX(5px); } }
214: @media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; } #scene.shake { animation: none; } }
215: @media (max-width: 1100px) {
216:   #app { padding-right: 24px; padding-left: 24px; }
217:   .layout { grid-template-columns: minmax(0, 1fr) 290px; gap: 17px; }
218:   .panel { padding: 13px; }
219:   .action { gap: 7px; padding: 0 8px; }
220:   .action b { font-size: 7px; }
221:   .action small { font-size: 6px; }
222: }
223: @media (max-width: 800px) {
