16:  function applyTheme(){document.documentElement.dataset.theme=theme;document.documentElement.style.colorScheme=theme==='dark'?'dark':'light';$('themeSelect').value=theme;let meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=theme==='dark'?'#111411':'#f3f2ed'}
17:  function applyLanguage(){document.documentElement.lang=language;$('languageSelect').value=language;document.querySelectorAll('[data-i18n]').forEach(el=>{let text=tr(el.dataset.i18n);if(!text)return;let node=[...el.childNodes].find(child=>child.nodeType===Node.TEXT_NODE&&child.textContent.trim());if(node)node.textContent=node.textContent.replace(node.textContent.trim(),text);else if(!el.children.length)el.textContent=text});$('languageSelect').setAttribute('aria-label',tr('language'));$('themeSelect').setAttribute('aria-label',tr('theme'));$('floorSelect').setAttribute('aria-label',tr('chooseFloor'));updateUI()}
