19: let s={...initial};try{const saved=JSON.parse(localStorage.getItem('ascendant-save'));if(saved)s={...initial,...saved,relics:Array.isArray(saved.relics)?saved.relics:[],defeatedBosses:Array.isArray(saved.defeatedBosses)?saved.defeatedBosses:[],clearedFloors:Array.isArray(saved.clearedFloors)?saved.clearedFloors:[],residentQuests:saved.residentQuests&&typeof saved.residentQuests==='object'?saved.residentQuests:{},metResidents:Array.isArray(saved.metResidents)?saved.metResidents:[]}}catch(e){}
