21: const pickTheme=()=>themes[Math.floor((s.floor-1)/10)%10];
22: function isBoss(f=s.floor){return f%10===0&&!s.defeatedBosses.includes(f)}
23: function isSafe(f=s.floor){return f%10===5}
24: function spawnEnemy(){let f=s.floor,t=pickTheme(),boss=isBoss(f),base=95+f*22+Math.floor(f/10)*35,hp=Math.round(base*(.68+enemiesLeft*.22));enemy={name:boss?bossNames[Math.ceil(f/10)-1]:t[2],hp,max:hp,atk:5+f*1.45,level:f,boss,attackTimer:2.1+Math.random()*1.8,windup:0,stun:0,flash:0,phase:0}}
25: function makeEnemy(){if(isSafe()){enemy=null;enemiesLeft=0;combatState='safe';return}enemiesLeft=isBoss()?1:Math.min(4,1+Math.floor((s.floor-1)/5));spawnEnemy();combatState='fight'}
26: function persist(){try{localStorage.setItem('ascendant-save',JSON.stringify(s))}catch(e){}}
27: function xpNeed(){return 100+(s.level-1)*65}
28: function log(text,kind=''){let d=document.createElement('div');d.className='log-entry';d.innerHTML=text; if(kind)d.classList.add(kind);$('combatLog').prepend(d);while($('combatLog').children.length>5)$('combatLog').lastChild.remove()}
29: function toast(text){let el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),900)}
