248:   .scene-wrap { height: 300px; min-height: 280px; }
249:   .scene-top { top: 12px; right: 11px; left: 11px; font-size: 7px; }
250:   .scene-tag { padding: 7px 8px; }
251:   .scene-bottom { right: 12px; bottom: 13px; left: 12px; }
252:   .scene-bottom strong { font-size: 12px; }
253:   .scene-bottom small { font-size: 7px; }
254:   .enemy-health { width: 43%; }
255:   .combat-row { height: 69px; }
256:   .hero-vitals { width: 53%; gap: 9px; }
257:   .portrait { width: 35px; height: 35px; }
258:   .combat-note { max-width: 145px; font-size: 0; text-align: right; line-height: 2; }
259:   .combat-note .keycap { font-size: 7px; }
260:   .combat-note .sep { margin: 0 4px; font-size: 8px; }
261:   .actions { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 7px; }
262:   .action { height: 55px; gap: 7px; padding: 0 10px; }
263:   .action-icon { width: 20px; font-size: 17px; }
264:   .sidebar { gap: 8px; }
265:   .panel { padding: 11px; }
266:   .panel-title { font-size: 7px; }
267:   .stats div { padding-left: 5px; }
268:   .stats small { font-size: 5px; }
269:   .stats b { font-size: 11px; }
270:   .floor-list { flex-wrap: wrap; }
271: }
272: @media (max-width: 370px) {
273:   .sidebar { grid-template-columns: 1fr; }
274:   .action { padding: 0 8px; }
275:   .action b { font-size: 7px; }
276:   .action small { font-size: 6px; }
277:   .floor-state { max-width: 110px; text-align: right; line-height: 1.6; }
278: }

