 const pickTheme=()=>themes[Math.floor((s.floor-1)/10)%10];
 function isBoss(f=s.floor){return f%10===0&&!s.defeatedBosses.includes(f)}
 function isSafe(f=s.floor){return f%10===5}
 function spawnEnemy(){let f=s.floor,t=pickTheme(),boss=isBoss(f),base=140+f*28+Math.floor(f/10)*100+f*f*.3,hp=Math.round(base*(.68+enemiesLeft*.22));enemy={name:boss?bossNames[Math.ceil(f/10)-1]:t[2],hp,max:hp,atk:7+f*.9+Math.floor(f/5)*2,level:f,boss,attackTimer:2.1+Math.random()*1.8,windup:0,stun:0,flash:0,phase:0}}
+ function attackInterval(){return Math.max(.3,.55-(s.agi-10)*.008)}
 function makeEnemy(){if(isSafe()){enemy=null;enemiesLeft=0;combatState='safe';return}enemiesLeft=isBoss()?1:Math.min(4,1+Math.floor((s.floor-1)/5));spawnEnemy();combatState='fight'}
