import http.server, json, os, socket, struct, subprocess, tempfile, threading, time, urllib.request, base64, hashlib
ROOT='/home/runner/work/PlayGround/PlayGround'
class Handler(http.server.SimpleHTTPRequestHandler):
    def __init__(self,*args,**kwargs): super().__init__(*args,directory=ROOT,**kwargs)
    def log_message(self,*args): pass
httpd=http.server.ThreadingHTTPServer(('127.0.0.1',8765),Handler)
threading.Thread(target=httpd.serve_forever,daemon=True).start()
profile=tempfile.mkdtemp(prefix='ascendant-chrome-')
proc=subprocess.Popen(['/usr/bin/chromium','--headless=new','--no-sandbox','--disable-gpu','--disable-dev-shm-usage','--remote-allow-origins=*','--remote-debugging-port=9222',f'--user-data-dir={profile}','about:blank'],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
def wait_url(url,timeout=10):
    deadline=time.time()+timeout
    while time.time()<deadline:
        try: return json.load(urllib.request.urlopen(url))
        except Exception: time.sleep(.1)
    raise RuntimeError('Chrome debugging endpoint did not start')
def connect_ws(url):
    from urllib.parse import urlparse
    u=urlparse(url); sock=socket.create_connection((u.hostname,u.port)); key=base64.b64encode(os.urandom(16)).decode()
    sock.sendall((f'GET {u.path} HTTP/1.1\r\nHost: {u.hostname}:{u.port}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: {key}\r\nSec-WebSocket-Version: 13\r\nOrigin: http://localhost\r\n\r\n').encode())
    resp=b''
    while b'\r\n\r\n' not in resp: resp+=sock.recv(1)
    if b'101' not in resp.split(b'\r\n')[0]: raise RuntimeError(resp.decode(errors='replace'))
    return sock
def send_frame(sock,payload):
    data=payload.encode(); mask=os.urandom(4); n=len(data); head=bytes([0x81,0x80|(n if n<126 else 126 if n<65536 else 127)])
    if n>=126: head+=struct.pack('!H',n) if n<65536 else struct.pack('!Q',n)
    sock.sendall(head+mask+bytes(b^mask[i%4] for i,b in enumerate(data)))
def recv_frame(sock):
    h=sock.recv(2)
    if len(h)<2: raise RuntimeError('WebSocket closed')
    n=h[1]&127
    if n==126:n=struct.unpack('!H',sock.recv(2))[0]
    elif n==127:n=struct.unpack('!Q',sock.recv(8))[0]
    mask=sock.recv(4) if h[1]&128 else None; data=b''
    while len(data)<n: data+=sock.recv(n-len(data))
    if mask:data=bytes(b^mask[i%4] for i,b in enumerate(data))
    return data.decode()
class CDP:
    def __init__(self,sock): self.sock=sock; self.i=0
    def call(self,method,params=None):
        self.i+=1; ident=self.i; send_frame(self.sock,json.dumps({'id':ident,'method':method,'params':params or {}}))
        while True:
            msg=json.loads(recv_frame(self.sock))
            if msg.get('id')==ident:
                if 'error' in msg: raise RuntimeError(msg['error'])
                return msg.get('result',{})
    def eval(self,expression,await_promise=False):
        r=self.call('Runtime.evaluate',{'expression':expression,'returnByValue':True,'awaitPromise':await_promise})
        if 'exceptionDetails' in r: raise RuntimeError(r['exceptionDetails'])
        return r.get('result',{}).get('value')
try:
    targets=wait_url('http://127.0.0.1:9222/json')
    target=next(t for t in targets if t['type']=='page')
    c=CDP(connect_ws(target['webSocketDebuggerUrl']))
    c.call('Page.enable'); c.call('Runtime.enable')
    c.call('Page.navigate',{'url':'http://127.0.0.1:8765/index.html'})
    time.sleep(1)
    # Death persistence and full-run reset
    dead={'floor':1,'level':1,'xp':0,'hp':1,'mp':50,'gold':50,'potions':3,'tonics':1,'kills':0,'str':10,'agi':10,'vit':10,'int':10,'points':0,'unlocked':1,'weapon':0,'weaponRarity':'common','armor':0,'ore':0,'loot':0,'relics':[],'won':False,'dead':False,'defeatedBosses':[],'clearedFloors':[],'residentQuests':{},'craftedArmor':0,'metResidents':[]}
    c.eval("localStorage.setItem('ascendant-save',"+json.dumps(json.dumps(dead))+ "); location.reload()")
    time.sleep(4)
    death=c.eval("JSON.stringify({modal:document.getElementById('modalTitle').textContent,button:document.getElementById('modalBtn').textContent,locked:document.getElementById('attackBtn').disabled,save:JSON.parse(localStorage.getItem('ascendant-save'))})")
    c.eval('location.reload()'); time.sleep(1)
    death_reload=c.eval("JSON.stringify({modal:document.getElementById('modalTitle').textContent,locked:document.getElementById('attackBtn').disabled,enemy:document.getElementById('enemyName').textContent})")
    c.eval("document.getElementById('modalBtn').click()")
    reset=c.eval("JSON.stringify({hidden:document.getElementById('modal').classList.contains('hidden'),floor:JSON.parse(localStorage.getItem('ascendant-save')).floor,dead:JSON.parse(localStorage.getItem('ascendant-save')).dead,level:JSON.parse(localStorage.getItem('ascendant-save')).level,attackDisabled:document.getElementById('attackBtn').disabled})")
    print('DEATH',death); print('DEATH_RELOAD',death_reload); print('DEATH_RESET',reset)
    # Valid XP progression: seeded near threshold, one high-damage enemy kill
    xp={'floor':1,'level':1,'xp':200,'hp':100,'mp':50,'gold':50,'potions':3,'tonics':1,'kills':0,'str':1000,'agi':10,'vit':10,'int':10,'points':0,'unlocked':1,'weapon':0,'weaponRarity':'common','armor':0,'ore':0,'loot':0,'relics':[],'won':False,'dead':False,'defeatedBosses':[],'clearedFloors':[],'residentQuests':{},'craftedArmor':0,'metResidents':[]}
    c.eval("localStorage.setItem('ascendant-save',"+json.dumps(json.dumps(xp))+ "); location.reload()")
    time.sleep(1); c.eval("document.getElementById('attackBtn').click()")
    xp_result=c.eval("JSON.stringify({level:JSON.parse(localStorage.getItem('ascendant-save')).level,points:JSON.parse(localStorage.getItem('ascendant-save')).points,xp:JSON.parse(localStorage.getItem('ascendant-save')).xp,cleared:JSON.parse(localStorage.getItem('ascendant-save')).clearedFloors})")
    print('XP',xp_result)
    # Floor 100 victory, restoration, and explicit full-run reset
    win={'floor':100,'level':30,'xp':0,'hp':100,'mp':50,'gold':50,'potions':3,'tonics':1,'kills':0,'str':100000,'agi':10,'vit':10,'int':10,'points':9,'unlocked':100,'weapon':3,'weaponRarity':'legendary','armor':4,'ore':3,'loot':4,'relics':[],'won':False,'dead':False,'defeatedBosses':[],'clearedFloors':[],'residentQuests':{},'craftedArmor':4,'metResidents':[]}
    c.eval("localStorage.setItem('ascendant-save',"+json.dumps(json.dumps(win))+ "); location.reload()")
    time.sleep(1); c.eval("document.getElementById('attackBtn').click()")
    victory=c.eval("JSON.stringify({title:document.getElementById('modalTitle').textContent,button:document.getElementById('modalBtn').textContent,save:JSON.parse(localStorage.getItem('ascendant-save'))})")
    c.eval('location.reload()'); time.sleep(1)
    victory_reload=c.eval("JSON.stringify({title:document.getElementById('modalTitle').textContent,button:document.getElementById('modalBtn').textContent,locked:document.getElementById('attackBtn').disabled,enemy:document.getElementById('enemyName').textContent})")
    c.eval("document.getElementById('modalBtn').click()")
    victory_reset=c.eval("JSON.stringify({hidden:document.getElementById('modal').classList.contains('hidden'),floor:JSON.parse(localStorage.getItem('ascendant-save')).floor,won:JSON.parse(localStorage.getItem('ascendant-save')).won,level:JSON.parse(localStorage.getItem('ascendant-save')).level,attackDisabled:document.getElementById('attackBtn').disabled})")
    print('VICTORY',victory); print('VICTORY_RELOAD',victory_reload); print('VICTORY_RESET',victory_reset)
finally:
    proc.terminate(); proc.wait(timeout=5); httpd.shutdown()

